import{_ as t,o,c as a,a2 as l}from"./chunks/framework.Crpw6aS5.js";const i=JSON.parse('{"title":"2003年 · 治理警世","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2003年.md","filePath":"05_quotes/by-year/2003年.md"}'),r={name:"05_quotes/by-year/2003年.md"};function u(s,e,c,h,q,_){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_2003年-·-治理警世" tabindex="-1">2003年 · 治理警世 <a class="header-anchor" href="#_2003年-·-治理警世" aria-label="Permalink to &quot;2003年 · 治理警世&quot;">​</a></h1><blockquote><p>如果美国正在进行阶级斗争，我的阶级显然正在获胜。——巴菲特（73岁）</p></blockquote><p>本页收录2003年致股东信中的经典语录。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>投资经理从积累资产中获利往往远多于妥善管理这些资产。所以当有人告诉你增加资金不会损害他的投资业绩时，请后退一步：他的鼻子快要变长了。</p></blockquote><blockquote><p>资本目前利用不足，但这会周期性发生。这是一种痛苦的状态——但不像做蠢事那样痛苦。（我是凭经验说的。）</p></blockquote><blockquote><p>谁会去洗租来的车？</p></blockquote><blockquote><p>你赢，他们赢大；你输，他们输大。我们的方法可以称为所有者资本主义。我知道没有更好的方法来激发真正的独立性。</p></blockquote><blockquote><p>如果你不知道某人站在哪一边，他可能不是站在你这一边。</p></blockquote><blockquote><p>&quot;董事会气氛&quot;几乎总是抑制他们的受托基因。</p></blockquote><blockquote><p>除了独立之外，董事还应具备商业头脑、股东导向和对公司真正的兴趣。这些品质中最罕见的是商业头脑——如果缺乏这一点，其他两个没什么帮助。</p></blockquote><blockquote><p>分析伯克希尔时，务必将公司视为一部展开的电影，而非一张静止照片。</p></blockquote><blockquote><p>当&quot;证券化&quot;在1990年代变得流行，进一步使资金提供者与借贷交易疏远时，该行业的行为从糟糕变得更糟。</p></blockquote><blockquote><p>如果只有540名纳税人缴纳伯克希尔将缴纳的金额，其他任何个人或公司都不需要向美国联邦政府缴纳一分钱的所得税。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2003年伯克希尔每股账面价值增长21%，落后标普500的28.7%。巴菲特以17亿美元收购克莱顿家园，从沃尔玛收购McLane公司仅用两小时谈判。本年他罕见进入外汇市场看空美元，并就公司治理发表尖锐批评，直指共同基金董事的&quot;哈巴狗式行为&quot;。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2003年-翻译-·-01-letters-2003年-核心总结-·-01-letters-2003年-思维导图" tabindex="-1"><a href="/01_letters/2003年/翻译.html">01_letters/2003年/翻译</a> · <a href="/01_letters/2003年/核心总结.html">01_letters/2003年/核心总结</a> · <a href="/01_letters/2003年/思维导图.html">01_letters/2003年/思维导图</a> <a class="header-anchor" href="#_01-letters-2003年-翻译-·-01-letters-2003年-核心总结-·-01-letters-2003年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2003年/翻译]] · [[→ 核心总结|01_letters/2003年/核心总结]] · [[→ 思维导图|01_letters/2003年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2003年/翻译.html">/01_letters/2003年/翻译</a></li></ul>',23)])])}const p=t(r,[["render",u]]);export{i as __pageData,p as default};
